values ('24-28605', '2024-12-11 08:35:25', 'DAÑOS A PROPIEDAD', 'DAÑOS A PROPIEDAD', 'Del reporte crp 856 contacta con dueño negocio Deposito Los Nietos, Carlos Acosta Ruiz de 38 años menciona que llegó el dia de hoy a las 7:40 su empleada la cual se percata de los daños que son a dos vidrios de 1 metro por 30 cm de la puerta principal valor 500 pesos total ,daños a cristal en ambos retrovisores en espejos ,parabrisas frontal estrellamiento de vehículo vw Combi color crema  y azul placa XLG1539  de tmps  valor del daño de 10 mil pesos ,negocio no cuenta con cámaras o alarma se interpone la denuncia por daños correspondiente.', 'Plutarco Elías Calles 606, Zona Tampiquito, Los Fresnos, 66240 San Pedro Garza García, N.L., México', 25.6494431, -100.3840164, '1018', '1', 'Llamada 911', '2024-12-11 01:57:31', '2024-12-11 02:00:00', 'Inspección(es), Entrevista(s)', 'Negocio', 'DEPOSITO', 'DEPOSITO LOS NIETOS', null, 'abierto', '{"fecha_registro":"11/12/2024 08:35:25","objetos_encontrados":"No","origen_id":"24-28605","origen":"P360 INFORMES.csv","negocio_operando":"NO","personas_entrevistadas":"5191090 CARLOS ACOSTA RUIZ","oficial_origen":"PP00022 Escobedo Navarro","objetos_faltantes":"No"}'::jsonb);
